"""sport template v8 (n112): the NFL landing surfaces, one for one.
  global bar  = SLATE chips (the day windows) · POS chips · GAME · TEAM · clear · SOURCE, with the find-player / team box (ctrl-K)
  Overview    = the KPI strip (slate · softest / stingiest D playing · bleeding / tightening · highest total · biggest spread ·
                model plays · props posted), team-colored slate tiles with implied totals, line, win%, both rank strips, the
                frozen plays, the win bar and the env line, then the edge board per slot
  Game View   = one game: header with line / O/U / ML / win%, softer field, env, missing men, last meeting, revenge; both rank
                strips; the two side tables (slot · player · usage · his /G · opponent allows /G with rank · PROJ with range ·
                LINE); the market block (number, model, gap, pick) and this game's player markets by edge
  Insights    = tempo & trend edges (helps / hurts) and who has the field and who doesn't, per slot
Rerunnable (guarded)."""
import os, sys
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'sport_template.html')
s = open(P, encoding='utf-8').read()
if 'function gameView()' in s:
    print('already applied'); sys.exit()
def rep(old, new):
    global s
    assert s.count(old) == 1, (s.count(old), old[:90])
    s = s.replace(old, new)
def cut(start, end_marker):
    global s
    a = s.index(start); b = s.index(end_marker, a); s = s[:a] + s[b:]

# ---- header + global bar markup ----
rep("""<nav id="tnav"></nav><span class="right"><a class="all" href="index.html">◍ sports</a>""",
    """<nav id="tnav"></nav><span class="right"><span class="finder"><input id="gFind" placeholder="find player / team" autocomplete="off"><kbd>ctrl-K</kbd><div id="gFindOut" hidden></div></span><a class="all" href="index.html">◍ sports</a>""")
rep("""<div id="gbar"><label>game</label><select id="gGame"><option value="">all games</option></select><label>team</label><select id="gTeam"><option value="">all teams</option></select><label>slot</label><span id="gSlots"></span><label>source</label><select id="gSrc"></select><span class="mini" id="gInfo"></span></div>""",
    """<div id="gbar"><label>slate</label><span id="gDays" class="dchips"></span><label>pos</label><span id="gSlots"></span><label>game</label><select id="gGame"><option value="">all games</option></select><label>team</label><select id="gTeam"><option value="">all teams</option></select><button class="mopen" id="gClear">✕ clear</button><label>source</label><select id="gSrc"></select><span class="mini" id="gInfo" style="margin-left:auto"></span></div>""")
rep(".mopen:hover{color:var(--txt);border-color:var(--acc)}",
    ".mopen:hover{color:var(--txt);border-color:var(--acc)}.finder{position:relative;display:inline-flex;align-items:center;gap:6px;border:1px solid var(--edge2);border-radius:7px;padding:3px 8px;background:var(--panel)}.finder input{background:none;border:0;color:var(--txt);font-family:var(--mono);font-size:11px;width:150px;outline:none}.finder kbd{font:10px var(--mono);color:var(--mute);border:1px solid var(--edge2);border-radius:4px;padding:0 4px}#gFindOut{position:absolute;top:30px;right:0;min-width:300px;max-height:360px;overflow:auto;background:var(--panel);border:1px solid var(--edge2);border-radius:8px;z-index:50;padding:4px}#gFindOut div{padding:5px 8px;cursor:pointer;font-size:12px;border-radius:5px}#gFindOut div:hover,#gFindOut div.on{background:var(--s3)}"
    "#gDays .dch,#gSlots .chip{min-height:24px}#gbar .dchips{display:inline-flex;gap:4px;flex-wrap:wrap}"
    ".kpis.strip{grid-template-columns:repeat(auto-fill,minmax(190px,1fr))}.kpi .v .tc img{width:18px;height:18px}"
    ".gt{border:1px solid var(--edge2);border-radius:10px;padding:8px 10px;min-width:0;cursor:pointer;position:relative}.gt .top{display:flex;justify-content:space-between;font-family:var(--mono);font-size:10px;color:var(--dim)}.gt .tms{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;margin:6px 0 2px;font-size:14px}.gt .tms .tc img{width:28px;height:28px}.gt .tms i{font-style:normal;font-family:var(--mono);font-size:11px;color:var(--txt);margin:0 6px}.gt .ln{font-family:var(--mono);font-size:11px;color:var(--txt)}.gt .ln .dim{margin-left:6px}.rstrip{display:grid;grid-template-columns:34px repeat(9,minmax(0,1fr));gap:2px;align-items:center;margin:3px 0;font-family:var(--mono);font-size:10px}.rstrip .badge{display:block;min-width:0;padding:0 2px;font-size:10px;line-height:1.5}.rstrip .lb{color:var(--dim);font-size:9px;text-align:center}.gt .plays{display:flex;flex-wrap:wrap;gap:4px;margin:5px 0;font-family:var(--mono);font-size:10px}.gt .plays span{border:1px solid var(--edge2);border-radius:4px;padding:1px 5px}.gt .wbar{display:grid;grid-template-columns:32px 1fr 32px;align-items:center;gap:6px;font-family:var(--mono);font-size:10px;margin:4px 0}.gt .wbar .b{height:6px;background:var(--s3);border-radius:3px;overflow:hidden}.gt .wbar .b i{display:block;height:100%;background:var(--green)}.gt .env{font-family:var(--mono);font-size:10px;color:var(--dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.sgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:10px}"
    ".eb{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.eb .ebc{background:var(--s2);border:1px solid var(--edge);border-radius:9px;padding:8px 10px}.eb table{width:100%;font-size:11.5px}.eb td{padding:3px 4px;white-space:nowrap}.eb.two{grid-template-columns:repeat(2,minmax(0,1fr))}.eb .ebc{min-width:0;overflow-x:auto}.eb .fb{display:inline-block;width:70px;height:7px;background:var(--s3);border-radius:3px;vertical-align:middle;overflow:hidden}.eb .fb i{display:block;height:100%}"
    ".gv .ghead{text-align:center;font-family:var(--mono);font-size:12px;padding:8px 0;border-bottom:1px solid var(--edge)}.gv .ghead b{font-size:14px}.gv .gline{font-family:var(--mono);font-size:11px;color:var(--dim);text-align:center;margin:3px 0}.gv .gsides{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:8px}.gv .side h4{margin:4px 0;font-size:12px}.gv table{width:100%;font-size:11.5px}.gv td,.gv th{padding:3px 4px;white-space:nowrap}.gv .side{min-width:0;overflow-x:auto}.gv .hc{min-width:36px;font-size:11px;padding:1px 3px}.gv .hc i{font-size:8.5px}.gv .his{white-space:normal;max-width:150px;line-height:1.3}.gv .usage{font-family:var(--mono);font-size:10px;color:var(--dim)}.gv .his{font-family:var(--mono);font-size:10px;color:var(--dim)}.gv .his b{color:var(--txt)}.gv .pbar{display:inline-block;width:60px;height:4px;background:var(--s3);vertical-align:middle;border-radius:2px;position:relative}.gv .pbar i{position:absolute;top:0;height:100%;background:var(--acc)}.gv .corner{display:grid;grid-template-columns:1fr 1fr;align-items:start}.gv .corner .r{text-align:right}.mk2{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.mk2>div{min-width:0;overflow-x:auto}@media(max-width:1100px){.gv .gsides,.mk2,.eb{grid-template-columns:1fr}}")

rep("""const tc=t=>`<span class="tc">${logo(t)}<span style="color:${TEAM[t]&&TEAM[t].color?'var(--tc-'+t+','+TEAM[t].color+')':'var(--dim)'}">${t}</span></span>`;""", r"""const lum=h=>{if(!h||h[0]!=='#'||h.length!==7)return 1;const v=parseInt(h.slice(1),16);return (0.2126*(v>>16)+0.7152*((v>>8)&255)+0.0722*(v&255))/255};
const vividHex=h=>lum(h)<0.18?'#9aa5b1':h;   /* black / navy clubs (BKN, SA, …) read as slate grey on the dark theme */
const tc=t=>`<span class="tc">${logo(t)}<span style="color:${TEAM[t]&&TEAM[t].color?(lum(TEAM[t].color)<0.18?vividHex(TEAM[t].color):'var(--tc-'+t+','+TEAM[t].color+')'):'var(--dim)'}">${t}</span></span>`;""")
# ---- global bar wiring: day chips + slot chips + clear + finder ----
rep("""  $('#gTeam').innerHTML+=Object.keys(TEAM).sort().map(t=>`<option>${t}</option>`).join('');$('#gSlots').innerHTML=J.slots.map(s=>`<span class="chip" data-s="${s}">${s}</span>`).join('');""",
    """  $('#gTeam').innerHTML+=Object.keys(TEAM).sort().map(t=>`<option>${t}</option>`).join('');$('#gSlots').innerHTML=`<span class="chip on" data-s="">all</span>`+J.slots.map(s=>`<span class="chip" data-s="${s}" style="color:${({G:'#6db3e8',F:'#a78bfa',C:'#e3b341',W:'#a78bfa',D:'#e3b341'})[s]||'inherit'}">${s}</span>`).join('');
  const dayBar=()=>{const N=DAYS();const cnt=d=>J.games.filter(g=>dayKey(g.date)===d).length;$('#gDays').innerHTML=`<button class="dch ${G.day==='all'?'on':''}" data-d="all">all <span class="dim">${J.games.length}</span></button>`+N.map(d=>`<button class="dch ${G.day===d?'on':''}" data-d="${d}">${d} <span class="dim">${cnt(d)}</span></button>`).join('');$('#gDays').querySelectorAll('.dch').forEach(b=>b.onclick=()=>{G.day=b.dataset.d;dayBar();render()})};dayBar();window.dayBar=dayBar;
  $('#gClear').onclick=()=>{G.game='';G.team='';G.slots=new Set();G.day=DAYS().length>1?DAYS()[0]:'all';$('#gGame').value='';$('#gTeam').value='';$('#gSlots').querySelectorAll('.chip').forEach(c=>c.classList.toggle('on',c.dataset.s===''));dayBar();render()};
  (()=>{const inp=$('#gFind'),out=$('#gFindOut');const items=()=>{const q=inp.value.trim().toLowerCase();if(q.length<2)return [];const T=Object.keys(TEAM).filter(t=>t.toLowerCase().startsWith(q)||(TEAM[t].name||'').toLowerCase().includes(q)).slice(0,4).map(t=>({t}));const P=J.players.filter(p=>p.player.toLowerCase().includes(q)).sort((a,b)=>(b.min||b.min_prior||0)-(a.min||a.min_prior||0)).slice(0,12).map(p=>({p}));return T.concat(P)};let sel=0;
    const draw=()=>{const R=items();out.hidden=!R.length;out.innerHTML=R.map((r,i)=>`<div class="${i===sel?'on':''}" data-i="${i}">${r.t?`${tc(r.t)} <span class="mini">${TEAM[r.t].name||''} · filter the page</span>`:`${esc(r.p.player)} <span class="mini">${r.p.team} · ${r.p.slot} · ${fmt(his(r.p,'min'),0)} min</span>`}</div>`).join('');out.querySelectorAll('div').forEach(d=>d.onclick=()=>pick(R[+d.dataset.i]))};
    const pick=r=>{out.hidden=true;inp.value='';if(!r)return;if(r.t){G.team=r.t;G.game='';$('#gTeam').value=r.t;$('#gGame').value='';render()}else openPlayer(r.p.pid)};
    inp.oninput=()=>{sel=0;draw()};inp.onkeydown=e=>{const R=items();if(e.key==='ArrowDown'){sel=Math.min(R.length-1,sel+1);draw();e.preventDefault()}else if(e.key==='ArrowUp'){sel=Math.max(0,sel-1);draw();e.preventDefault()}else if(e.key==='Enter'){pick(R[sel])}else if(e.key==='Escape'){out.hidden=true;inp.blur()}};inp.onblur=()=>setTimeout(()=>out.hidden=true,150);
    document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();inp.focus();inp.select()}})})();""")
rep("""  $('#gSlots').querySelectorAll('.chip').forEach(c=>c.onclick=()=>{G.slots.has(c.dataset.s)?G.slots.delete(c.dataset.s):G.slots.add(c.dataset.s);c.classList.toggle('on');render()});""",
    """  $('#gSlots').querySelectorAll('.chip').forEach(c=>c.onclick=()=>{const s=c.dataset.s;if(!s)G.slots=new Set();else{G.slots.has(s)?G.slots.delete(s):G.slots.add(s)}$('#gSlots').querySelectorAll('.chip').forEach(x=>x.classList.toggle('on',x.dataset.s?G.slots.has(x.dataset.s):!G.slots.size));render()});""")
# the per-view day chips are now the global slate chips
rep("const dayChips=()=>`<span class=\"dchips\">", "const dayChips=()=>``;const _dayChipsOld=()=>`<span class=\"dchips\">")
rep("const bindDays=el=>el.querySelectorAll('.dch').forEach(b=>b.onclick=()=>{G.day=b.dataset.d;render()});", "const bindDays=el=>{};")

# ---- Overview ----
cut("function home(){", "/* ---- v3 helpers")
rep("/* ---- MATCHUPS ---- */", r"""const hex2rgba=(h,a)=>{if(!h||h[0]!=='#')return `rgba(120,120,120,${a})`;const v=parseInt(h.slice(1),16);return `rgba(${v>>16},${(v>>8)&255},${v&255},${a})`};
const tcol=t=>TEAM[t]&&TEAM[t].color||'#666';
let _DT=null;function defTrend(){if(_DT)return _DT;const by={};J.logs.forEach(l=>{if(l[LC.season]!==J.cur)return;const d=l[LC.opp],g=l[LC.date];const o=by[d]=by[d]||{};o[g]=(o[g]||0)+(+l[LC.pts]||0)});const out={};Object.entries(by).forEach(([t,o])=>{const g=Object.entries(o).sort((a,b)=>a[0]<b[0]?-1:1).map(x=>x[1]);const n=g.length;const pr=J.dvp[String(J.prior)]&&J.dvp[String(J.prior)][t]?J.slots.map(sl=>J.dvp[String(J.prior)][t][sl]&&J.dvp[String(J.prior)][t][sl].pts?J.dvp[String(J.prior)][t][sl].pts.avg:0).reduce((a,b)=>a+b,0):null;
    const se=n>=10||pr==null?mean(g):(g.reduce((a,b)=>a+b,0)+pr*(10-n))/10;const l10=mean(g.slice(-10)),l5=mean(g.slice(-5));const rec=n>=10?l10:l5;out[t]={se,l10,l5,n,prior:pr,d:se&&rec!=null?100*(rec-se)/se:null}});return _DT=out}
const teamPsi=t=>mean(J.slots.map(sl=>psiOf(t,sl)).filter(v=>v!=null));
const gamePicks=g=>J.picks.filter(p=>p.game===g.away+'@'+g.home&&(p.date===g.day||p.type==='PROP'&&p.date===g.day));
const dkProj=p=>{const pj=PJ[p.pid]||{};let v=0,ok=false;Object.entries(DKS).forEach(([k,w])=>{const r=pj[k];if(r){ok=true;v+=r.proj*w}else if(p[k]!=null)v+=p[k]*w});return ok?v:null};
const revengeIn=g=>{const A=rotation(g.away).slice(0,J.rotation+2).filter(p=>teamHist(p.pid).some(x=>x.t===g.home)),B=rotation(g.home).slice(0,J.rotation+2).filter(p=>teamHist(p.pid).some(x=>x.t===g.away));return A.concat(B)};
const missingIn=t=>rotation(t).slice(0,J.rotation+2).filter(p=>MISSED().has(p.pid));
const rankStrip=(off,def)=>{const ks=['pts','reb','ast'];return `<div class="rstrip"><span class="lb" style="color:${TEAM[off]?'var(--tc-'+off+','+tcol(off)+')':'var(--dim)'};font-weight:700">${off}</span>${J.slots.flatMap(sl=>ks.map(k=>{const r=rankOf(def,sl,k);return badge(r?r.rank:null)})).join('')}</div>`};
const stripHead=()=>`<div class="rstrip"><span></span>${J.slots.flatMap(sl=>['PTS','REB','AST'].map(k=>`<span class="lb">${sl} ${k}</span>`)).join('')}</div>`;
function gameTile(g){const k=g.away+'@'+g.home;const P=gamePicks(g);const pk=P.map(p=>`<span title="${p.type} ${esc(String(p.side))} ${p.line??''} · model ${p.model} · edge ${p.edge}">${p.type==='PROP'?`${esc(p.player.split(' ').slice(-1)[0])} ${p.side[0]}${p.line}`:p.type==='ML'?`ML ${esc(String(p.side))} ${p.model!=null?(100*p.model).toFixed(0)+'%':''}`:p.type==='ATS'?`ATS ${esc(String(p.side))} ${p.line>0?'+':''}${p.line}`:`O/U ${String(p.side)[0]} ${p.line}`}</span>`).join('');
  const rv=revengeIn(g).length,mA=missingIn(g.away),mH=missingIn(g.home);const ms=meetings(g.away,g.home);const last=ms[0];const DT=defTrend();
  const env=[`pace ${PACE_RK[g.away]||'·'} / ${PACE_RK[g.home]||'·'}`,rv?`revenge ×${rv}`:'',last?`last: ${g.away} ${last[g.away]}-${last[g.home]} ${g.home}`:'',mA.length?`${g.away} ${mA.length} out?`:'',mH.length?`${g.home} ${mH.length} out?`:''].filter(Boolean).join(' · ');
  const ph=g.p_home!=null?g.p_home:null;const fav=g.home_line!=null?(g.home_line<0?g.home:g.away):'';
  return `<div class="gt" data-g="${k}" style="background:linear-gradient(120deg,${hex2rgba(tcol(g.away),.28)},${hex2rgba(tcol(g.home),.28)}),var(--s2)"><div class="top"><span>${dayKey(g.date)} · ${fmtT(g.date)} CT${g.stype==='pre'?' · PRE':''}</span><span>${esc(g.tv||'')}</span></div>
   <div class="tms"><span class="tc">${tc(g.away)}<i>${g.away_implied??''}</i></span><span class="dim">@</span><span class="tc" style="justify-content:flex-end"><i>${g.home_implied??''}</i>${tc(g.home)}</span></div>
   <div class="ln">${g.odds?`<b>${lineTxt(g)}</b>`:'<span class="dim">no line</span>'}${g.ou?` <span class="dim">·</span> O/U <b>${g.ou}</b>`:''}${ph!=null?` <span class="dim">· K ${g.home} ${(100*ph).toFixed(0)}%</span>`:''}${g.away_rec?` <span class="dim">· ${g.away} ${g.away_rec} · ${g.home} ${g.home_rec}</span>`:''}</div>
   ${stripHead()}${rankStrip(g.away,g.home)}${rankStrip(g.home,g.away)}
   <div class="plays">${pk||'<span class="dim" style="border:0;padding:0">no line frozen</span>'}</div>
   ${ph!=null?`<div class="wbar"><span>${g.away}</span><span class="b"><i style="width:${(100*ph).toFixed(0)}%;margin-left:auto"></i></span><span style="text-align:right">${g.home}</span></div>`:''}
   <div class="env" title="${esc(env)}">${env}</div></div>`}
function home(){const el=$('#home');const gs=GAMESD();const DT=defTrend();const T=[...new Set(gs.flatMap(g=>[g.away,g.home]))];
  const soft=T.map(t=>({t,v:teamPsi(t)})).filter(x=>x.v!=null).sort((a,b)=>a.v-b.v);const bleed=T.map(t=>({t,v:DT[t]?DT[t].d:null})).filter(x=>x.v!=null).sort((a,b)=>b.v-a.v);
  const tot=gs.filter(g=>g.ou).sort((a,b)=>parseFloat(b.ou)-parseFloat(a.ou))[0];const spr=gs.filter(g=>g.home_line!=null).sort((a,b)=>Math.abs(b.home_line)-Math.abs(a.home_line))[0];
  const plays=gs.flatMap(gamePicks);const pr=PR.filter(r=>gs.some(g=>g.away===r.team||g.home===r.team));
  const k=(t,v,s,cls='')=>`<div class="kpi ${cls}"><div class="k">${t}</div><div class="v">${v}</div><div class="s">${s}</div></div>`;
  const kp=`<div class="kpis strip">${k('slate',`${gs.length} games`,`${G.day==='all'?'next 14 days':G.day} · ${T.length} teams`)}${soft[0]?k('softest D playing',tc(soft[0].t),`mean Ψ ${soft[0].v.toFixed(1)} across ${J.slots.join(' · ')}`):''}${soft.length?k('stingiest D playing',tc(soft[soft.length-1].t),`mean Ψ ${soft[soft.length-1].v.toFixed(1)}`):''}${bleed[0]?k('bleeding lately',tc(bleed[0].t),`lately ${bleed[0].v>0?'+':''}${bleed[0].v.toFixed(0)}% PTS allowed vs its baseline (last 5 until ten games are in, then last 10)`):''}${bleed.length?k('tightening',tc(bleed[bleed.length-1].t),`lately ${bleed[bleed.length-1].v.toFixed(0)}% vs its baseline`):''}${tot?k('highest total',`${tc(tot.away)} @ ${tc(tot.home)}`,`O/U ${tot.ou} · ${tot.home_implied!=null?tot.away+' '+tot.away_implied+' · '+tot.home+' '+tot.home_implied:''}`):''}${spr?k('biggest spread',`${tc(spr.home_line<0?spr.home:spr.away)} ${Math.abs(spr.home_line)}`,`${spr.away} @ ${spr.home}${spr.p_home!=null?' · K '+spr.home+' '+(100*spr.p_home).toFixed(0)+'%':''}`):''}${k('model plays',`<span class="${plays.length?'rise':''}">${plays.length}</span>`,`frozen on this slate · ${plays.filter(p=>p.type==='PROP').length} props · ${plays.filter(p=>p.type!=='PROP').length} game plays`)}${k('props posted',pr.length,`player-markets on this slate · ${pr.filter(okProp).filter(r=>r.edge>=.05).length} clear the bar`)}</div>`;
  const tiles=`<div class="panel"><h3>${G.day==='all'?'the window':G.day} slate <span class="f">implied team totals beside the logos · line, O/U, K = model win probability · both rank strips: what the OPPONENT allows to each slot in PTS · REB · AST (1 = allows the most) · frozen plays · the win bar · env = pace ranks, revenge games, last meeting, missing men · click a tile for its game view</span></h3><div class="sgrid">${gs.map(gameTile).join('')||'<p class="note">no games on this slate</p>'}</div></div>`;
  const U=univ();const eb=`<div class="panel"><h3>edge board — ${G.day==='all'?'the window':G.day} <span class="f">per slot, the softest fields: Ψ = the opponent's mean rank across PTS REB AST 3PM STL BLK for his slot (bar = how soft) · PTS/G his own · DK = DraftKings-scoring projection · PROJ = points</span></h3><div class="eb">${J.slots.map(sl=>{const R=U.filter(p=>p.slot===sl).map(p=>({p,psi:psiOf(oppT(p.team),p.slot)})).filter(x=>x.psi!=null).sort((a,b)=>a.psi-b.psi);const top=R.slice(0,6),bot=R.slice(-4).reverse();
    const row=x=>{const w=Math.max(4,100*(NT-x.psi)/(NT-1));return `<tr><td>${pname(x.p)} <span class="mini">${oppOf(x.p.team)}</span></td><td><span class="fb"><i style="width:${w.toFixed(0)}%;background:${gradeColor(x.psi)}"></i></span> <span class="psi" style="color:${gradeColor(x.psi)}">${x.psi.toFixed(1)}</span></td><td class="mono">${fmt(x.p.pts,1)}</td><td class="mono">${fmt(dkProj(x.p),1)}</td><td class="mono"><b>${PJ[x.p.pid]&&PJ[x.p.pid].pts?fmt(PJ[x.p.pid].pts.proj,1):'·'}</b></td></tr>`};
    return `<div class="ebc"><div class="k" style="font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--acc);margin-bottom:4px">${posIcon(sl,12)} ${sl} <span class="mini">${R.length} on the slate</span></div><table><thead><tr><th>player</th><th>field Ψ</th><th>PTS/G</th><th>DK</th><th>PROJ</th></tr></thead><tbody>${top.map(row).join('')}${bot.length?`<tr><td colspan="5" class="mini" style="color:var(--red)">hardest fields</td></tr>`+bot.map(row).join(''):''}</tbody></table></div>`}).join('')}</div></div>`;
  // standings & ratings + leaders (kept from v1)
  const wp=r=>(r.wins+r.losses)?r.wins/(r.wins+r.losses):0;const rat=Object.values(J.ratings).filter(r=>inT(r.team)).sort((a,b)=>wp(b)-wp(a)||(b.pf-b.pa)-(a.pf-a.pa));
  const ratings=`<div class="panel wrap-x"><h3>standings &amp; ratings <span class="f">this season's record first · rating = blended scoring margin · pace = points for + against · every header sorts</span></h3><table><thead><tr><th>#</th><th>team</th><th>W-L</th><th>win%</th><th>PF/g</th><th>PA/g</th><th>±/g</th><th>rating</th><th>pace</th><th>L10 ±</th><th>next</th><th>D Ψ</th></tr></thead><tbody>${rat.map((r,i)=>`<tr><td class="mini">${i+1}</td><td>${tc(r.team)}</td><td class="mono"><b>${r.wins}-${r.losses}</b></td><td class="mono">${(100*wp(r)).toFixed(0)}%</td><td>${fmt(r.pf,1)}</td><td>${fmt(r.pa,1)}</td><td class="${r.pf-r.pa>0?'rise':'fall'}">${r.pf-r.pa>0?'+':''}${fmt(r.pf-r.pa,1)}</td><td><b class="${r.rating>0?'rise':'fall'}">${r.rating>0?'+':''}${fmt(r.rating,1)}</b></td><td>${fmt(r.pace,1)}</td><td class="mono">${r.l10!=null?(r.l10>0?'+':'')+fmt(r.l10,1):'·'}</td><td class="mini">${oppOf(r.team)}</td><td>${psiCell(teamPsi(r.team))}</td></tr>`).join('')}</tbody></table></div>`;
  el.innerHTML=kp+tiles+eb+ratings;el.querySelectorAll('.gt[data-g]').forEach(t=>t.onclick=()=>{G.gv=t.dataset.g;go('cards')});bindPL(el)}
/* ---- MATCHUPS ---- */""")

