rep("function weeklies2(){", r"""function insights(){const el=$('#home');const DT=defTrend();const U=univ().filter(p=>p.gp>=2||p.gp_prior>=20);
  const rows=U.map(p=>{const opp=oppT(p.team);const psi=psiOf(opp,p.slot);const t=DT[opp];const pace=PACE_RK[opp];const pj=PJ[p.pid]&&PJ[p.pid].pts;return {p,opp,psi,trend:t?t.d:null,pace,proj:pj?pj.proj:null,home:nextGame(p.team)?.home===p.team}}).filter(x=>x.psi!=null);
  const helps=rows.filter(x=>x.pace!=null&&x.pace<=8&&x.trend!=null&&x.trend>=3).sort((a,b)=>(b.trend+(NT-b.pace))-(a.trend+(NT-a.pace))).slice(0,10);const hurts=rows.filter(x=>x.pace!=null&&x.pace>=NT-7&&x.trend!=null&&x.trend<=-3).sort((a,b)=>(a.trend-(NT-a.pace))-(b.trend-(NT-b.pace))).slice(0,10);
  const srow=x=>`<tr><td>${pname(x.p)} ${slotchip(x.p.slot)}</td><td class="mini">${x.home?'vs':'@'}</td><td>${tc(x.opp)}</td><td class="mini">pace #${x.pace} · D L10 ${x.trend>0?'+':''}${x.trend.toFixed(0)}% PTS vs season</td><td class="mono" style="color:${x.trend>0?'var(--green)':'var(--red)'}">${x.trend>0?'+':''}${x.trend.toFixed(0)}%</td><td>${psiCell(x.psi)}</td><td class="mono"><b>${fmt(x.proj,1)}</b></td><td class="mini">${fmt(his(x.p,'min'),0)} min</td></tr>`;
  const tempo=`<div class="panel"><h3>tempo &amp; trend edges — ${G.day==='all'?'the window':G.day} <span class="f">the style helps = the opponent plays fast (top-8 pace) and has been bleeding points lately (L10 vs season) · hurts = slow and tightening · Ψ = the opponent's mean rank for his slot · PROJ = points</span></h3><div class="mk2"><div><div class="mini" style="color:var(--green);margin:4px 0">the style helps</div><table><thead><tr><th>player</th><th></th><th>vs</th><th>defense style</th><th>trend</th><th>Ψ</th><th>PROJ</th><th>min</th></tr></thead><tbody>${helps.map(srow).join('')||'<tr><td colspan="8" class="mini">nothing on this slate</td></tr>'}</tbody></table></div><div><div class="mini" style="color:var(--red);margin:4px 0">the style hurts</div><table><thead><tr><th>player</th><th></th><th>vs</th><th>defense style</th><th>trend</th><th>Ψ</th><th>PROJ</th><th>min</th></tr></thead><tbody>${hurts.map(srow).join('')||'<tr><td colspan="8" class="mini">nothing on this slate</td></tr>'}</tbody></table></div></div></div>`;
  const field=`<div class="panel"><h3>${G.day==='all'?'the window':G.day} — who has the field and who doesn't <span class="f">per slot: target = the softest fields (bar = how soft, Ψ beside it) · avoid = the hardest · the opponent after the @/vs</span></h3><div class="eb two">${J.slots.map(sl=>{const R=rows.filter(x=>x.p.slot===sl).sort((a,b)=>a.psi-b.psi);const li=(x,good)=>`<tr><td>${pname(x.p)}</td><td><span class="fb"><i style="width:${Math.max(4,100*(good?(NT-x.psi):(x.psi))/(NT-1)).toFixed(0)}%;background:${good?'var(--green)':'var(--red)'}"></i></span> <span class="psi" style="color:${gradeColor(x.psi)}">${x.psi.toFixed(1)}</span></td><td class="mini">${x.home?'vs':'@'}</td><td>${tc(x.opp)}</td></tr>`;
    return `<div class="ebc"><div class="k" style="font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--acc);margin-bottom:4px">${posIcon(sl,12)} ${sl} <span class="mini">${R.length} on the slate</span></div><div class="mk2" style="margin:0"><div><div class="mini" style="color:var(--green)">target — softest fields</div><table><tbody>${R.slice(0,6).map(x=>li(x,true)).join('')}</tbody></table></div><div><div class="mini" style="color:var(--red)">avoid — hardest fields</div><table><tbody>${R.slice(-6).reverse().map(x=>li(x,false)).join('')}</tbody></table></div></div></div>`}).join('')}</div></div>`;
  const hot=U.filter(p=>p.gp>=3&&p.pts_l5!=null&&p.pts>=8).map(p=>({p,d:p.pts_l5-p.pts})).sort((a,b)=>b.d-a.d);
  const mv=[];Object.keys(D()).forEach(t=>J.slots.forEach(sl=>{const a=rankOf(t,sl,'pts',String(J.cur)),b=rankOf(t,sl,'pts',String(J.prior));if(a&&b)mv.push({t,sl,d:a.rank-b.rank,a:a.rank,b:b.rank})}));mv.sort((x,y)=>Math.abs(y.d)-Math.abs(x.d));
  const be=PR.filter(okProp).sort((a,b)=>b.edge-a.edge).slice(0,8);
  const three=`<div class="eb"><div class="panel"><h3>hot &amp; cold <span class="f">last five vs season, PTS</span></h3>${hot.slice(0,6).map(x=>`<div class="mbr2"><span class="nm">${pname(x.p)} <span class="mini">${x.p.team}</span></span><b class="rise">+${x.d.toFixed(1)}</b></div>`).join('')}<hr style="border:0;border-top:1px solid var(--edge)">${hot.slice(-6).reverse().map(x=>`<div class="mbr2"><span class="nm">${pname(x.p)} <span class="mini">${x.p.team}</span></span><b class="fall">${x.d.toFixed(1)}</b></div>`).join('')}</div>
   <div class="panel"><h3>defensive movers <span class="f">PTS allowed rank, ${J.cur} vs ${J.prior} · + = softer now</span></h3>${mv.slice(0,12).map(x=>`<div class="mbr2"><span class="nm">${tc(x.t)} ${slotchip(x.sl)}</span><span class="mono">${x.b} → ${x.a}</span><b class="${x.d<0?'rise':'fall'}">${x.d<0?'+':''}${-x.d}</b></div>`).join('')}</div>
   <div class="panel"><h3>best prop edges <span class="f">model vs market, both sides priced</span></h3>${be.map(r=>`<div class="mbr2"><span class="nm">${pname(r)} <span class="mini">${MKL[r.market]||r.market} ${r.line}</span></span>${lean(r)}</div>`).join('')||'<span class="mini">no props posted</span>'}</div></div>`;
  el.innerHTML=tempo+field+three;bindPL(el)}
function weeklies2(){""")
